a:15:{s:9:"reason_id";s:24:"did-not-work-as-expected";s:11:"reason_info";s:884:"I am Hamzah from Wise Owl Institute. I have checked the audio plugin, it is not working and does not generate the audio after all the batch numbers are updated, the audio plugin only reads the story title. I also cleaned the cache but no result at the moment.
Furthermore, I think we have invested enough time on this plugin issue, and we still don\'t have a proper solution, and it affects the traffic of our website. 

As Aqib and you have been in communication for a long time now and the issue still persists, we would like to go for another option and would like to kindly ask you for refund from you for the PRO version since we don\'t have a reliable bug-free solution. The only reason to buy the PRO version was not to have any issues, even if we translated or added a big blog post. Unfortunately, the PRO version is not as reliable as it is shown and not up to expectations.";s:10:"user_email";s:23:"hamzahkhan673@gmail.com";s:9:"user_name";s:17:"Hamzah Ahmed Khan";s:6:"server";a:11:{s:8:"software";s:6:"Apache";s:11:"php_version";s:8:"8.0.30.1";s:13:"mysql_version";s:6:"8.0.33";s:18:"php_execution_time";s:3:"300";s:19:"php_max_upload_size";s:6:"100 MB";s:20:"php_default_timezone";s:3:"UTC";s:8:"php_soap";s:3:"Yes";s:13:"php_fsockopen";s:3:"Yes";s:8:"php_curl";s:3:"Yes";s:7:"php_ftp";s:3:"Yes";s:8:"php_sftp";s:2:"No";}s:8:"software";s:6:"Apache";s:11:"php_version";s:8:"8.0.30.1";s:13:"mysql_version";s:6:"8.0.33";s:2:"wp";a:5:{s:12:"memory_limit";s:3:"40M";s:10:"debug_mode";s:2:"No";s:6:"locale";s:5:"en_US";s:7:"version";s:5:"6.5.2";s:9:"multisite";s:2:"No";}s:10:"wp_version";s:5:"6.5.2";s:6:"locale";s:5:"en_US";s:9:"multisite";s:2:"No";s:10:"ip_address";s:14:"160.153.154.21";s:7:"version";s:5:"1.6.4";s:6:"client";s:5:"1.0.0";}

