a:15:{s:9:"reason_id";s:21:"not-have-that-feature";s:11:"reason_info";s:480:"Unfortunately, none of the external TTS presented works in Russia. I would like to be able to connect to TTS, which is open in Russia.

The TTS of the plugin in the pro version is better than the basic one. But there are pages on my site where there are both Russian and English languages, and recognition occurs only for one language. There is no adaptation to the English words that appear in the text.

Well, I would like to be able to change the voice, at least male / female.";s:10:"user_email";s:17:"support@medfsh.ru";s:9:"user_name";s:5:"admin";s:6:"server";a:11:{s:8:"software";s:13:"Apache/2.4.65";s:11:"php_version";s:6:"8.3.30";s:13:"mysql_version";s:6:"5.7.35";s:18:"php_execution_time";s:3:"800";s:19:"php_max_upload_size";s:6:"5 ГБ";s:20:"php_default_timezone";s:3:"UTC";s:8:"php_soap";s:3:"Yes";s:13:"php_fsockopen";s:3:"Yes";s:8:"php_curl";s:3:"Yes";s:7:"php_ftp";s:3:"Yes";s:8:"php_sftp";s:3:"Yes";}s:8:"software";s:13:"Apache/2.4.65";s:11:"php_version";s:6:"8.3.30";s:13:"mysql_version";s:6:"5.7.35";s:2:"wp";a:5:{s:12:"memory_limit";s:5:"1024M";s:10:"debug_mode";s:2:"No";s:6:"locale";s:5:"ru_RU";s:7:"version";s:5:"6.9.4";s:9:"multisite";s:2:"No";}s:10:"wp_version";s:5:"6.9.4";s:6:"locale";s:5:"ru_RU";s:9:"multisite";s:2:"No";s:10:"ip_address";s:23:"2a03:6f00:6:1::517:32cf";s:7:"version";s:6:"2.1.12";s:6:"client";s:5:"1.0.0";}
